import bpy,json,numpy as np,sys
from pathlib import Path
D=Path(__file__).resolve().parent;sys.path.insert(0,str(D));from aov_tools import attach,configure_files,read_outputs,statistics

def setup_iron_aovs(sc):
 key=sys.argv[sys.argv.index('--')+1];C=D/key;out=D/'aov'/('after' if key=='11_restored_pigment' else 'before');out.mkdir(parents=True,exist_ok=True);obj=sc.objects['Lab Chest Lower Rim'];obj.data=obj.data.copy();mat=obj.data.materials[0].copy();obj.data.materials[0]=mat;nt=mat.node_tree;black=nt.nodes['Blackened conductive iron'];bare=nt.nodes['Exposed iron Filament diagnostic reflectance'];oxide=nt.nodes['Opaque dark oxide and forge scale'];geo=nt.nodes.new('ShaderNodeNewGeometry');geo.name='Diagnostic actual geometry normal'
 signals=[('Iron_BaseBlack','COLOR',black.inputs['Base Color']),('Iron_BaseOxide','COLOR',oxide.inputs['Base Color']),('Iron_BaseBare','COLOR',bare.inputs['Base Color']),('Iron_RoughBlack','VALUE',black.inputs['Roughness']),('Iron_RoughOxide','VALUE',oxide.inputs['Roughness']),('Iron_RoughBare','VALUE',bare.inputs['Roughness']),('Iron_MetalFe','VALUE',bare.inputs['Metallic']),('Iron_MetalOxide','VALUE',oxide.inputs['Metallic']),('Iron_OxideCoverage','VALUE',nt.nodes['Opaque scale coverage'].inputs[0]),('Iron_ExposedBlend','VALUE',nt.nodes['Localized exposed iron'].inputs[0]),('Iron_FacetWear','VALUE',next(n for n in nt.nodes if n.type=='ATTRIBUTE' and n.attribute_name=='Damaged bevel facet wear').outputs['Fac']),('Iron_MarkHeight','VALUE',nt.nodes['Independent shallow fractured scale markings'].inputs['Height']),('Iron_FineHeight','VALUE',nt.nodes['fine16.png independent strength'].inputs['Height']),('Iron_PigmentSource','VALUE',nt.nodes['Character pigment.png'].outputs['Color']),('Iron_FinalNormal','COLOR',black.inputs['Normal']),('Iron_GeometryNormal','COLOR',geo.outputs['True Normal']),('Iron_SurfaceAlpha','VALUE',black.inputs['Alpha'])]
 records,nodes=attach(sc,mat,signals);names=[s[0] for s in signals];writers=configure_files(sc,names,out);sc.render.resolution_x=1600;sc.render.resolution_y=800;sc.render.resolution_percentage=100;sc.render.use_border=True;sc.render.use_crop_to_border=True;sc.render.border_min_x=.23;sc.render.border_max_x=.81;sc.render.border_min_y=.20;sc.render.border_max_y=.68;sc.cycles.samples=48;sc.cycles.seed=17;sc.render.filepath=str(out/'beauty.png');sc.render.image_settings.file_format='PNG';sc.render.image_settings.color_mode='RGBA';(out/'signals.json').write_text(json.dumps(records,indent=2));bpy.ops.render.render(write_still=True);arrays=read_outputs(out,names);stats,scope=statistics(arrays,'Iron_SurfaceAlpha');np.savez_compressed(out/'passes.npz',**arrays);(out/'statistics.json').write_text(json.dumps(stats,indent=2))
 assert np.max(abs(arrays['Iron_MetalFe'][scope]-1))<1e-5;assert np.max(abs(arrays['Iron_MetalOxide'][scope]))<1e-7;assert np.max(abs(arrays['Iron_BaseBare'][scope]-np.array([.55201143,.5647115,.5647115])))<1e-5
