 proof=dict(version=bpy.app.version_string,passes_verified=names,exposed_color_scene_linear_verified=True,clean_metal_constant_one_verified=True,oxide_metal_constant_zero_verified=True,zero_channel_control_verified=True,scope_pixels=int(scope.sum()),production_bsdf_values_unchanged=True,diagnostics_only_in_temporary_copy=True);(out/'verification.json').write_text(json.dumps(proof,indent=2));print('AOV VERIFIED',json.dumps(proof),flush=True)
